	private static function privacy_has_more($uid){global $wpdb;$checks=array(array('playback_sessions','user_id'),array('interactions','user_id'),array('download_tokens','user_id'),array('upload_sessions','owner_id'),array('live_poll_responses','user_id'),array('broadcast_guests','user_id'),array('live_attendees','user_id'),array('live_questions','user_id'),array('moderation','reporter_id'),array('audit','actor_id'),array('creator_metrics_daily','owner_id'),array('production_sources','owner_id'),array('production_scenes','owner_id'),array('simulcast_targets','created_by'),array('media_tracks','created_by'),array('media_tracks','reviewed_by'),array('video_annotations','created_by'),array('video_annotations','reviewed_by'),array('live_polls','created_by'),array('consent_links','created_by'),array('watermark_policies','updated_by'),array('broadcast_guests','invited_by'),array('captions','created_by'),array('captions','reviewed_by'),array('stream_credentials','created_by'),array('moderation','reviewer_id'),array('takedowns','claimant_id'),array('takedowns','reviewer_id'));foreach($checks as $spec){$t=VWLB_Helpers::table($spec[0]);if($wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE {$spec[1]}=%d LIMIT 1",$uid)))return true;}$idem=VWLB_Helpers::table('idempotency');$scope='%'.$wpdb->esc_like(':u'.$uid).'%';return (bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM $idem WHERE scope LIKE %s LIMIT 1",$scope));}
	public static function erase($email,$page=1){
		$user=get_user_by('email',$email);if(!$user)return array('items_removed'=>false,'items_retained'=>false,'messages'=>array(),'done'=>true);global $wpdb;$uid=(int)$user->ID;$removed=false;$messages=array();
		$upload_rows=$wpdb->get_results($wpdb->prepare('SELECT id,private_filename,status FROM '.VWLB_Helpers::table('upload_sessions').' WHERE owner_id=%d ORDER BY id ASC LIMIT 100',$uid),ARRAY_A);foreach((array)$upload_rows as $s){if(!empty($s['private_filename'])){$base=trailingslashit(WP_CONTENT_DIR).VWLB_Extensions::PRIVATE_DIR;$path=$base.'/'.sanitize_file_name($s['private_filename']);if(is_file($path)&&!unlink($path))return array('items_removed'=>$removed,'items_retained'=>true,'messages'=>array(__('A private upload could not be deleted from storage; retry safely.',VWLB_TEXT_DOMAIN)),'done'=>false);}}
		$interaction_rows=$wpdb->get_results($wpdb->prepare('SELECT id,video_id FROM '.VWLB_Helpers::table('interactions').' WHERE user_id=%d ORDER BY id ASC LIMIT 100',$uid),ARRAY_A);$interaction_ids=array_column((array)$interaction_rows,'id');$affected=array_values(array_unique(array_map('intval',array_column((array)$interaction_rows,'video_id'))));
		$result=VWLB_DB::transaction(function()use($wpdb,$uid,$upload_rows,$interaction_ids,$affected,&$removed){
			foreach(array(array('playback_sessions','user_id'),array('download_tokens','user_id'),array('live_poll_responses','user_id'),array('broadcast_guests','user_id')) as $spec){$t=VWLB_Helpers::table($spec[0]);$n=$wpdb->query($wpdb->prepare("DELETE FROM $t WHERE {$spec[1]}=%d ORDER BY id ASC LIMIT 100",$uid));if(false===$n)return VWLB_Helpers::error('vwlb_privacy_delete_failed',__('Privacy erasure failed safely.',VWLB_TEXT_DOMAIN),500);$removed=$removed||$n>0;}
			if($upload_rows){$ids=array_column($upload_rows,'id');if(!self::delete_ids('upload_sessions',$ids))return VWLB_Helpers::error('vwlb_privacy_delete_failed',__('Private upload records could not be erased.',VWLB_TEXT_DOMAIN),500);$removed=true;}
			if($interaction_ids){if(!self::delete_ids('interactions',$interaction_ids))return VWLB_Helpers::error('vwlb_privacy_delete_failed',__('Interaction records could not be erased.',VWLB_TEXT_DOMAIN),500);$removed=true;foreach($affected as $video_id)foreach(array('like','dislike') as $type){$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.VWLB_Helpers::table('interactions').' WHERE video_id=%d AND interaction=%s',$video_id,$type));$changed=$wpdb->update(VWLB_Helpers::table('videos'),array($type.'_count'=>$count),array('id'=>$video_id));if(false===$changed)return VWLB_Helpers::error('vwlb_privacy_counter_failed',__('Interaction counters could not be reconciled.',VWLB_TEXT_DOMAIN),500);}}
			$attendees=$wpdb->get_results($wpdb->prepare('SELECT id,public_id,live_event_id FROM '.VWLB_Helpers::table('live_attendees').' WHERE user_id=%d ORDER BY id ASC LIMIT 100',$uid),ARRAY_A);foreach((array)$attendees as $row){$anon=self::anonymized_user_id($row['live_event_id'],$row['public_id']);if(!$anon)return VWLB_Helpers::error('vwlb_privacy_anonymize_failed',__('An anonymous attendee identity could not be allocated safely.',VWLB_TEXT_DOMAIN),500);$changed=$wpdb->update(VWLB_Helpers::table('live_attendees'),array('user_id'=>$anon,'state'=>'anonymized','updated_at'=>VWLB_Helpers::now()),array('id'=>$row['id'],'user_id'=>$uid));if(1!==$changed)return VWLB_Helpers::error('vwlb_privacy_anonymize_failed',__('Attendance could not be anonymized safely.',VWLB_TEXT_DOMAIN),500);}
			$anonymize=array(array('live_questions','user_id',array('user_id'=>0,'question'=>'[erased by privacy request]')),array('moderation','reporter_id',array('reporter_id'=>0,'note'=>'[anonymized by privacy erasure]')),array('audit','actor_id',array('actor_id'=>0)),array('creator_metrics_daily','owner_id',array('owner_id'=>0)),array('production_sources','owner_id',array('owner_id'=>0)),array('production_scenes','owner_id',array('owner_id'=>0)),array('simulcast_targets','created_by',array('created_by'=>0)),array('media_tracks','created_by',array('created_by'=>0)),array('media_tracks','reviewed_by',array('reviewed_by'=>0)),array('video_annotations','created_by',array('created_by'=>0)),array('video_annotations','reviewed_by',array('reviewed_by'=>0)),array('live_polls','created_by',array('created_by'=>0)),array('consent_links','created_by',array('created_by'=>0)),array('watermark_policies','updated_by',array('updated_by'=>0)),array('broadcast_guests','invited_by',array('invited_by'=>0)),array('captions','created_by',array('created_by'=>0)),array('captions','reviewed_by',array('reviewed_by'=>0)),array('stream_credentials','created_by',array('created_by'=>0)),array('moderation','reviewer_id',array('reviewer_id'=>0)),array('takedowns','claimant_id',array('claimant_id'=>0,'claimant_contact_hash'=>'')),array('takedowns','reviewer_id',array('reviewer_id'=>0)));
			foreach($anonymize as $spec){$sets=array();$args=array();foreach($spec[2] as $field=>$value){$sets[]="$field=%s";$args[]=(string)$value;}$args[]=$uid;$args[]=100;$t=VWLB_Helpers::table($spec[0]);$n=$wpdb->query($wpdb->prepare("UPDATE $t SET ".implode(',',$sets)." WHERE {$spec[1]}=%d ORDER BY id ASC LIMIT %d",$args));if(false===$n)return VWLB_Helpers::error('vwlb_privacy_anonymize_failed',__('Retained privacy data could not be anonymized.',VWLB_TEXT_DOMAIN),500);}
			$idem=VWLB_Helpers::table('idempotency');$like='%'.$wpdb->esc_like(':u'.$uid).'%';$n=$wpdb->query($wpdb->prepare("DELETE FROM $idem WHERE scope LIKE %s LIMIT 200",$like));if(false===$n)return VWLB_Helpers::error('vwlb_privacy_delete_failed',__('Historical idempotency records could not be erased.',VWLB_TEXT_DOMAIN),500);return true;
		});
		if(is_wp_error($result))return array('items_removed'=>$removed,'items_retained'=>true,'messages'=>array($result->get_error_message()),'done'=>false);$done=!self::privacy_has_more($uid);if($done){VWLB_Helpers::audit('privacy',VWLB_Helpers::public_id('erase'),'erase','','complete','Eligible File 10 data erased/anonymized.',array('purpose'=>'privacy_erasure','subject'=>'anonymized'));$messages[]=__('Retained safety/rights evidence was anonymized where required.',VWLB_TEXT_DOMAIN);}else{$messages[]=__('One bounded File 10 erasure batch completed; additional eligible records remain.',VWLB_TEXT_DOMAIN);}return array('items_removed'=>$removed,'items_retained'=>true,'messages'=>$messages,'done'=>$done);
	}

	public static function cleanup_hardening(){global $wpdb;$now=VWLB_Helpers::now();foreach(array('idempotency'=>'expires_at','rate_limits'=>'window_ends_at','playback_sessions'=>'expires_at','rollback_snapshots'=>'expires_at') as $table=>$column){$n=$wpdb->query($wpdb->prepare('DELETE FROM '.VWLB_Helpers::table($table)." WHERE $column IS NOT NULL AND $column<%s LIMIT 1000",$now));if(false===$n)do_action('vwlb_operational_failure','cleanup','vwlb_cleanup_delete_failed',array('table'=>$table));}$n=$wpdb->query($wpdb->prepare('UPDATE '.VWLB_Helpers::table('stream_credentials')." SET status='expired' WHERE status='active' AND expires_at IS NOT NULL AND expires_at<%s LIMIT 1000",$now));if(false===$n)do_action('vwlb_operational_failure','cleanup','vwlb_stream_credential_expiry_failed',array());$n=$wpdb->query($wpdb->prepare('UPDATE '.VWLB_Helpers::table('download_tokens')." SET status='expired',updated_at=%s WHERE status='active' AND expires_at<%s LIMIT 1000",$now,$now));if(false===$n)do_action('vwlb_operational_failure','cleanup','vwlb_download_token_expiry_failed',array());}

	public static function capture_inbox_retry($event_id,$event_name,$payload){$event_id=VWLB_Helpers::text($event_id,100);if(!$event_id)return;$key=self::INBOX_RETRY_PREFIX.hash('sha256',$event_id);$record=array('event_id'=>$event_id,'event_name'=>VWLB_Helpers::text($event_name,100),'payload'=>(array)$payload,'payload_hash'=>hash('sha256',VWLB_Helpers::json_encode($payload)),'captured_at'=>VWLB_Helpers::now());update_option($key,$record,false);}
