	private static function retry_options($prefix,$limit=50){global $wpdb;$like=$wpdb->esc_like($prefix).'%';return $wpdb->get_results($wpdb->prepare("SELECT option_name,option_value FROM {$wpdb->options} WHERE option_name LIKE %s ORDER BY option_id ASC LIMIT %d",$like,max(1,min(100,$limit))),ARRAY_A);}
	public static function reconcile_inbox_retries(){global $wpdb;$table=VWLB_Helpers::table('inbox');foreach(self::retry_options(self::INBOX_RETRY_PREFIX,25) as $option){$record=maybe_unserialize($option['option_value']);if(!is_array($record)||empty($record['event_id'])){delete_option($option['option_name']);continue;}$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE event_id=%s LIMIT 1",$record['event_id']),ARRAY_A);if($row&&'processed'===$row['status']){delete_option($option['option_name']);continue;}if($row&&'processing'===$row['status']&&strtotime($row['received_at'].' UTC')>time()-15*MINUTE_IN_SECONDS)continue;if($row&&!hash_equals((string)$row['payload_hash'],(string)$record['payload_hash'])){do_action('vwlb_operational_failure','inbox','vwlb_inbox_retry_hash_conflict',array('event_id_hash'=>hash('sha256',$record['event_id'])));continue;}if($row){$deleted=$wpdb->delete($table,array('id'=>$row['id']),array('%d'));if(1!==$deleted)continue;}$consumer=new VWLB_Integrations();$result=$consumer->consume($record['event_id'],$record['event_name'],$record['payload']);if(!is_wp_error($result)&&!empty($result['processed']))delete_option($option['option_name']);}}

	public static function reconcile_fallbacks(){global $wpdb;foreach(self::retry_options(self::AUDIT_FALLBACK_PREFIX,50) as $option){$r=maybe_unserialize($option['option_value']);if(!is_array($r)){delete_option($option['option_name']);continue;}$saved=$wpdb->insert(VWLB_Helpers::table('audit'),$r);if($saved)delete_option($option['option_name']);}foreach(self::retry_options(self::OUTBOX_FALLBACK_PREFIX,50) as $option){$r=maybe_unserialize($option['option_value']);if(!is_array($r)){delete_option($option['option_name']);continue;}$saved=$wpdb->insert(VWLB_Helpers::table('outbox'),$r);if($saved)delete_option($option['option_name']);}}
